contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amount) public payable {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 targetBalBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        c.mintToken(target, amount); if (__ESBMC_reverted()) return;

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 targetBalAfter = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 ownerBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(supplyAfter == supplyBefore + amount
            && targetBalAfter == targetBalBefore + amount
            && (target == address(this)
                ? ownerBalAfter == ownerBalBefore + amount
                : ownerBalAfter == ownerBalBefore));
    }

    receive() external payable {}
}

